def box(a,b,texture='stone'):
 return {'from':a,'to':b,'faces':{f:{'texture':'#'+texture} for f in ['north','south','east','west','up','down']}}
def model(elements,textures,item=False):
 m={'parent':'minecraft:block/block','textures':textures,'elements':elements,'ambientocclusion':True}
 if item:m['display']={'gui':{'rotation':[15,0,0],'translation':[0,0,0],'scale':[1.1,1.1,1.1]},'ground':{'rotation':[90,0,0],'translation':[0,2,0],'scale':[.5,.5,.5]},'fixed':{'rotation':[0,180,0],'translation':[0,0,0],'scale':[.7,.7,.7]},'thirdperson_righthand':{'rotation':[0,0,0],'translation':[0,2,0],'scale':[.45,.45,.45]},'firstperson_righthand':{'rotation':[0,-25,0],'translation':[1,2,0],'scale':[.6,.6,.6]}}
 return m
